#!/usr/bin/env node
/**
 * Step 1: Mel spectrogram verification.
 * Compare library WhisperMelProcessor + padToFrames against saved reference JSON.
 *
 * Reference was generated by the same library (scripts/whisper-webgpu-smoke.sh):
 *   mel.process(samples) → padToFrames(result, 3000) → JSON.stringify(Array.from(padded))
 *
 * Usage:
 *   node tests/smoke/verify-step1-mel.mjs
 *   AUDIO_PATH=tests/fixtures/jfk2.en.wav node tests/smoke/verify-step1-mel.mjs
 */
import fs from 'node:fs';
import { WhisperMelProcessor } from '../../dist/audio/whisper-mel.js';

// ── Config ──
const AUDIO_PATH = process.env.AUDIO_PATH || '/mnt/n/github/asrjs/webgpu-agent-test/jfk2.en.wav';
const REF_PATH = 'tests/smoke/jfk2-mel-128.json';
const N_MELS = 128;
const TARGET_FRAMES = 3000; // Whisper 30s window at 100fps

// ── Audio loading ──
function loadWavMono(path) {
  const b = fs.readFileSync(path);
  let off = 12, fmt = null, data = null;
  while (off + 8 <= b.length) {
    const id = b.toString('ascii', off, off + 4), sz = b.readUInt32LE(off + 4), st = off + 8;
    if (id === 'fmt ') fmt = { channels: b.readUInt16LE(st + 2), sampleRate: b.readUInt32LE(st + 4), bitsPerSample: b.readUInt16LE(st + 14) };
    else if (id === 'data') data = b.subarray(st, st + sz);
    off = st + sz + (sz % 2);
  }
  if (!fmt || !data) throw new Error('bad wav');
  const bytes = fmt.bitsPerSample / 8, frames = Math.floor(data.length / bytes / fmt.channels);
  const out = new Float32Array(frames);
  for (let i = 0; i < frames; i++) {
    let s = 0;
    for (let ch = 0; ch < fmt.channels; ch++) {
      const p = (i * fmt.channels + ch) * bytes;
      s += data.readInt16LE(p) / 32768;
    }
    out[i] = s / fmt.channels;
  }
  // Resample to 16kHz if needed
  if (fmt.sampleRate === 16000) return out;
  const r = 16000 / fmt.sampleRate, o = new Float32Array(Math.max(1, Math.floor(out.length * r)));
  for (let i = 0; i < o.length; i++) {
    const x = i / r, x0 = Math.floor(x), x1 = Math.min(out.length - 1, x0 + 1), t = x - x0;
    o[i] = (out[x0] ?? 0) * (1 - t) + (out[x1] ?? 0) * t;
  }
  return o;
}

// ── Main ──
function main() {
  console.log('═══════════════════════════════════════════');
  console.log('Step 1: Mel Spectrogram Verification');
  console.log('═══════════════════════════════════════════');

  // Load reference (flat array, channels-first layout: [mel * frames + frame])
  const refFlat = JSON.parse(fs.readFileSync(REF_PATH, 'utf-8').trim());
  const refFrames = Math.floor(refFlat.length / N_MELS);
  console.log(`Reference: ${REF_PATH}`);
  console.log(`  Values: ${refFlat.length} = ${refFrames} frames × ${N_MELS} mels`);

  // Load audio
  const pcm = loadWavMono(AUDIO_PATH);
  console.log(`Audio: ${AUDIO_PATH}`);
  console.log(`  ${pcm.length} samples @ ${(pcm.length / (16000)).toFixed(1)}s`);

  // Compute mel via library + padToFrames (same as reference generation)
  const processor = new WhisperMelProcessor({ nMels: N_MELS });
  const melResult = processor.process(pcm);
  const padded = WhisperMelProcessor.padToFrames(melResult, TARGET_FRAMES);
  console.log(`Library: ${melResult.frameCount} raw frames → padTo ${TARGET_FRAMES} = ${padded.length} values`);

  // Compare padded vs reference (both should be identical layout)
  const compareLen = Math.min(refFlat.length, padded.length);
  let mse = 0, maxDiff = 0, sumRef = 0, sumLib = 0;
  for (let i = 0; i < compareLen; i++) {
    const diff = refFlat[i] - padded[i];
    mse += diff * diff;
    if (Math.abs(diff) > maxDiff) maxDiff = Math.abs(diff);
    sumRef += refFlat[i];
    sumLib += padded[i];
  }
  mse /= compareLen;

  // Sample values from frame 0
  console.log(`\nFrame 0 sample (first 8 mels):`);
  console.log(`  Ref:  ${refFlat.slice(0, 8).map(v => v.toFixed(4)).join(', ')}`);
  console.log(`  Lib:  ${Array.from(padded.slice(0, 8)).map(v => v.toFixed(4)).join(', ')}`);
  // Frame 500 if available
  if (compareLen > 500 * N_MELS) {
    const off = 500 * N_MELS;
    console.log(`Frame 500 (first 8 mels):`);
    console.log(`  Ref:  ${refFlat.slice(off, off + 8).map(v => v.toFixed(4)).join(', ')}`);
    console.log(`  Lib:  ${Array.from(padded.slice(off, off + 8)).map(v => v.toFixed(4)).join(', ')}`);
  }

  console.log(`\nResults:`);
  console.log(`  Compared elements: ${compareLen}`);
  console.log(`  MSE: ${mse.toExponential(4)}`);
  console.log(`  Max diff: ${maxDiff.toExponential(4)}`);
  console.log(`  Ref mean: ${(sumRef / compareLen).toFixed(4)}`);
  console.log(`  Lib mean: ${(sumLib / compareLen).toFixed(4)}`);

  const pass = mse < 1e-8; // Should be ~0 since same code generated ref
  console.log(`\nStatus: ${pass ? '✅ PASS' : '❌ FAIL'} (threshold: MSE < 1e-8)`);

  if (!pass && mse > 0.001) {
    console.log(`\nNOTE: Large mismatch. Possible causes:`);
    console.log(`  1. Different audio file (tests/fixtures/jfk2.en.wav vs ${AUDIO_PATH})`);
    console.log(`  2. Reference was generated with different code/params`);
    console.log(`  3. Library code changed since reference was generated`);
    console.log(`\nRun with AUDIO_PATH=tests/fixtures/jfk2.en.wav to compare with known-good audio:`);
    console.log(`  AUDIO_PATH=tests/fixtures/jfk2.en.wav node tests/smoke/verify-step1-mel.mjs`);
  }

  process.exit(pass ? 0 : 1);
}

main();
